function bestEventValue(events: number[][], k: number): number {
  const ev = [...events].sort((a, b) => a[0] - b[0]);
  const go = (i: number, lastEnd: number, left: number): number => {
    if (i === ev.length || left === 0) return 0;
    let best = go(i + 1, lastEnd, left);
    if (ev[i][0] > lastEnd) best = Math.max(best, ev[i][2] + go(i + 1, ev[i][1], left - 1));
    return best;
  };
  return go(0, 0, k);
}

