class Solution:
    def bestEventValue(self, events: List[List[int]], k: int) -> int:
        ev = sorted(events)

        def go(i, last_end, left):
            if i == len(ev) or left == 0:
                return 0
            best = go(i + 1, last_end, left)
            if ev[i][0] > last_end:
                best = max(best, ev[i][2] + go(i + 1, ev[i][1], left - 1))
            return best

        return go(0, 0, k)

