function bestEventValue(events: number[][], k: number): number {
  const ev = [...events].sort((a, b) => a[0] - b[0]);
  const n = ev.length;
  const next = new Array<number>(n);
  for (let i = 0; i < n; i++) {
    let lo = i + 1, hi = n; // first index with start > ev[i].end
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (ev[mid][0] > ev[i][1]) hi = mid; else lo = mid + 1;
    }
    next[i] = lo;
  }
  let prev = new Array<number>(n + 1).fill(0);
  for (let j = 1; j <= k; j++) {
    const cur = new Array<number>(n + 1).fill(0);
    for (let i = n - 1; i >= 0; i--) {
      cur[i] = Math.max(cur[i + 1], ev[i][2] + prev[next[i]]);
    }
    prev = cur;
  }
  return prev[0];
}

